import { ButtonGroup, type ButtonGroupActionDetail } from '@absoluteui/components/button-group';

const host = document.createElement('div');
document.body.append(host);
ButtonGroup.create(host, {
  label: 'Pagination',
  size: 'sm',
  buttons: [
    { icon: 'chevron-left', label: 'Previous page', value: 'prev' },
    { icon: 'chevron-right', label: 'Next page', value: 'next' },
  ],
});
host.addEventListener('aui-action', (event) => {
  const { value } = (event as CustomEvent<ButtonGroupActionDetail>).detail;
  host.dataset.last = value;
});

import { ButtonGroup } from '@absoluteui/components/button-group';

const element = document.createElement('div');
for (const text of ['Copy', 'Paste', 'Duplicate']) {
  const button = document.createElement('button');
  button.type = 'button';
  button.textContent = text;
  element.append(button);
}
document.body.append(element);
ButtonGroup.enhance(element, { label: 'Clipboard', attached: false });
